#include "chart.h"
#include <wincrypt.h>
#include <algorithm>
#include <cstring>
#include <sstream>
#include <iomanip>
#pragma comment(lib,"advapi32.lib")
namespace forest {
Progress progress;
std::recursive_mutex progressMutex;
namespace {
std::wstring rootPath;
std::vector<int> pending;
int lastStory=0;
uint32_t runEpoch=0;   // run journal replaced wholesale (new game, load, engine rollback, truncation, unknown) -> marks taken before are void
struct Writer {std::vector<uint8_t>b;void u(uint32_t x){for(int n=0;n<4;++n)b.push_back((uint8_t)(x>>(n*8)));}void run(const RunState&r){u(r.known);u(r.currentScript);u(r.currentChoice);u(r.currentPc);u((uint32_t)r.events.size());for(auto&e:r.events){u(e.kind);u(e.script);u(e.choice);u(e.option);u(e.pc);}}};
struct Reader {const std::vector<uint8_t>&b;size_t p=0;bool ok=true;uint32_t u(){if(p+4>b.size()){ok=false;return 0;}uint32_t v=0;for(int n=0;n<4;++n)v|=(uint32_t)b[p++]<<(n*8);return v;}RunState run(){RunState r;r.known=u()!=0;r.currentScript=(int)u();r.currentChoice=(int)u();r.currentPc=u();unsigned n=u();if(n>50000){ok=false;return r;}for(unsigned i=0;i<n&&ok;++i){Event e{(int)u(),(int)u(),(int)u(),(int)u(),u()};if(e.kind<1||e.kind>5||e.choice<-1||e.choice>=(int)choices.size()||e.option<0||e.option>(e.kind==Restart?9:5)){ok=false;break;}r.events.push_back(e);}return r;}};
bool rawRead(const std::wstring&p,std::vector<uint8_t>&b){HANDLE f=CreateFileW(p.c_str(),GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);if(f==INVALID_HANDLE_VALUE)return false;LARGE_INTEGER s{};bool ok=GetFileSizeEx(f,&s)&&s.QuadPart>=0&&s.QuadPart<=16*1024*1024;if(ok){b.resize((size_t)s.QuadPart);DWORD got=0;ok=ReadFile(f,b.data(),(DWORD)b.size(),&got,nullptr)&&got==b.size();}CloseHandle(f);return ok;}
bool read(const std::wstring&p,std::vector<uint8_t>&payload){std::vector<uint8_t>b;if(!rawRead(p,b)||b.size()<136)return false;if(memcmp(b.data(),"FCTRACK3",8)||memcmp(b.data()+8,modelIdentity.data(),64))return false;payload.assign(b.begin()+136,b.end());auto hash=Digest(payload.data(),payload.size());return hash.size()==64&&memcmp(b.data()+72,hash.data(),64)==0;}
bool write(const std::wstring&p,const std::vector<uint8_t>&payload){auto hash=Digest(payload.data(),payload.size());if(hash.empty())return false;std::string h="FCTRACK3"+modelIdentity+hash;std::wstring tmp=p+L".tmp";HANDLE f=CreateFileW(tmp.c_str(),GENERIC_WRITE,0,nullptr,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,nullptr);if(f==INVALID_HANDLE_VALUE)return false;DWORD n=0;bool ok=WriteFile(f,h.data(),(DWORD)h.size(),&n,nullptr)&&n==h.size();if(ok)ok=WriteFile(f,payload.data(),(DWORD)payload.size(),&n,nullptr)&&n==payload.size();if(ok)ok=FlushFileBuffers(f)!=FALSE;CloseHandle(f);if(!ok)return false;std::vector<uint8_t>old;if(read(p,old))CopyFileW(p.c_str(),(p+L".bak").c_str(),FALSE);return MoveFileExW(tmp.c_str(),p.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)!=FALSE;}
void append(int kind,int script,int choice=-1,int option=0,uint32_t pc=0){if(progress.run.events.size()>=50000){++runEpoch;progress.run.known=false;progress.run.events.erase(progress.run.events.begin(),progress.run.events.begin()+10000);Log("journal history truncated; earlier history unknown");}progress.run.events.push_back({kind,script,choice,option,pc});}
void choose(int id,int option){auto&c=choices[id];append(OptionChosen,c.script,id,option,c.pc);progress.chosenOptions.insert({id,option});progress.run.currentChoice=id;
 // Retry option 1 is accepted only for the audited 1300/1400/1500/1600 retry scripts.
 if(c.category==2&&option==1){int ch=c.script==1300?2:c.script==1400?3:c.script==1500?4:c.script==1600?5:-1;if(ch>=0)append(Restart,c.script,-1,ch+1,c.pc);}
 Log("choice "+c.id+" option "+std::to_string(option));PersistProgress();}
}
std::string Digest(const void*data,size_t size){HCRYPTPROV p=0;HCRYPTHASH h=0;std::string result;if(!CryptAcquireContextW(&p,nullptr,nullptr,PROV_RSA_AES,CRYPT_VERIFYCONTEXT))return result;if(CryptCreateHash(p,CALG_SHA_256,0,0,&h)&&CryptHashData(h,(const BYTE*)data,(DWORD)size,0)){BYTE hash[32];DWORD n=sizeof(hash);if(CryptGetHashParam(h,HP_HASHVAL,hash,&n,0)){std::ostringstream s;for(BYTE b:hash)s<<std::hex<<std::setw(2)<<std::setfill('0')<<(int)b;result=s.str();}}if(h)CryptDestroyHash(h);CryptReleaseContext(p,0);return result;}
std::string DigestFile(const std::wstring&path){std::vector<uint8_t>b;return rawRead(path,b)?Digest(b.data(),b.size()):std::string();}
void Log(const std::string&message){if(rootPath.empty())return;std::string line=std::to_string(GetTickCount64())+" "+message+"\r\n";HANDLE f=CreateFileW((rootPath+L"\\events.log").c_str(),FILE_APPEND_DATA,FILE_SHARE_READ,nullptr,OPEN_ALWAYS,FILE_ATTRIBUTE_NORMAL,nullptr);if(f==INVALID_HANDLE_VALUE)return;DWORD n;WriteFile(f,line.data(),(DWORD)line.size(),&n,nullptr);CloseHandle(f);}
Progress SnapshotProgress(){std::lock_guard<std::recursive_mutex> lock(progressMutex);return progress;}
void UnknownRun(const std::string& reason){std::lock_guard<std::recursive_mutex> lock(progressMutex);++runEpoch;progress.run=RunState();progress.primary=RunState();progress.secondary=RunState();pending.clear();lastStory=0;Log(reason);}
bool SceneKnown(int script){std::lock_guard<std::recursive_mutex> lock(progressMutex);return progress.reachedScenes.count(script)!=0||progress.run.currentScript==script;}
int CurrentSelection(int id){std::lock_guard<std::recursive_mutex> lock(progressMutex);if(id<0||id>=(int)choices.size())return -1;int chapter=choices[id].chapter;for(auto it=progress.run.events.rbegin();it!=progress.run.events.rend();++it){if(it->kind==Restart&&it->option==chapter+1)return -1;if(it->kind==OptionChosen&&it->choice==id)return it->option;}return -1;}
void LoadProgress(const std::wstring&root){std::lock_guard<std::recursive_mutex> lock(progressMutex);rootPath=root;CreateDirectoryW(root.c_str(),nullptr);CreateDirectoryW((root+L"\\saves").c_str(),nullptr);progress=Progress();pending.clear();lastStory=0;std::vector<uint8_t>b;if(!read(root+L"\\cumulative.dat",b)){if(!read(root+L"\\cumulative.dat.bak",b)){Log("no compatible cumulative history; start unknown");return;}Log("recovered cumulative history from validated backup");}Reader r{b};Progress p;unsigned n=r.u();if(n>52)r.ok=false;for(unsigned i=0;i<n&&r.ok;++i){int s=(int)r.u();if(SceneIndex(s)<0)r.ok=false;else p.reachedScenes.insert(s);}n=r.u();if(n>52)r.ok=false;for(unsigned i=0;i<n&&r.ok;++i){int s=(int)r.u();if(SceneIndex(s)<0)r.ok=false;else p.completedScenes.insert(s);}n=r.u();if(n>choices.size())r.ok=false;for(unsigned i=0;i<n&&r.ok;++i){int c=(int)r.u();if(c<0||c>=(int)choices.size())r.ok=false;else p.reachedChoices.insert(c);}n=r.u();if(n>505)r.ok=false;for(unsigned i=0;i<n&&r.ok;++i){int c=(int)r.u(),o=(int)r.u();if(c<0||c>=(int)choices.size()||o<1||o>(int)choices[c].options.size())r.ok=false;else p.chosenOptions.insert({c,o});}if(r.ok&&r.p==b.size())progress=p;else Log("cumulative payload invalid; prior history unknown");}
void PersistProgress(){std::lock_guard<std::recursive_mutex> lock(progressMutex);if(rootPath.empty())return;Writer w;w.u((uint32_t)progress.reachedScenes.size());for(int s:progress.reachedScenes)w.u(s);w.u((uint32_t)progress.completedScenes.size());for(int s:progress.completedScenes)w.u(s);w.u((uint32_t)progress.reachedChoices.size());for(int c:progress.reachedChoices)w.u(c);w.u((uint32_t)progress.chosenOptions.size());for(auto x:progress.chosenOptions){w.u(x.first);w.u(x.second);}if(!write(rootPath+L"\\cumulative.dat",w.b))Log("ERROR cumulative history could not be saved");}
void ObserveOpcode(int script,uint32_t pc,uint16_t op){std::lock_guard<std::recursive_mutex> lock(progressMutex);
 if(script==1&&pc==0){progress.run.currentScript=0;progress.run.currentChoice=-1;progress.run.currentPc=0;pending.clear();lastStory=0;}
 if(script==100&&pc==0){++runEpoch;progress.run=RunState();progress.run.known=true;progress.primary=RunState();progress.secondary=RunState();pending.clear();lastStory=0;Log("new game");}
 for(int k=(int)pending.size()-1;k>=0;--k){int id=pending[k];if(choices[id].script!=script)continue;auto&opts=choices[id].options;for(size_t j=0;j<opts.size();++j)if(opts[j].target==pc){choose(id,(int)j+1);pending.erase(pending.begin()+k,pending.end());k=-1;break;}}
 int si=SceneIndex(script);if(si>=0){if(lastStory!=script){append(SceneEnter,script,-1,0,pc);progress.reachedScenes.insert(script);lastStory=script;progress.run.currentChoice=-1;Log("scene "+std::to_string(script));PersistProgress();}progress.run.currentScript=script;progress.run.currentPc=pc;
 if(op==16||op==8||op==12){append(SceneExit,script,-1,0,pc);progress.completedScenes.insert(script);PersistProgress();}}
 if(op==14){for(size_t i=0;i<choices.size();++i){auto&c=choices[i];if(c.script==script&&c.pc==pc&&c.category!=3){int id=(int)i;append(ChoiceReached,script,id,0,pc);progress.reachedChoices.insert(id);progress.run.currentChoice=id;progress.run.currentScript=script;progress.run.currentPc=pc;if(std::find(pending.begin(),pending.end(),id)==pending.end())pending.push_back(id);PersistProgress();break;}}}
}
void CapturePrimary(){std::lock_guard<std::recursive_mutex> lock(progressMutex);progress.primary=progress.run;}
void CaptureSecondary(){std::lock_guard<std::recursive_mutex> lock(progressMutex);progress.secondary=progress.primary;}
void RestoreSecondary(){std::lock_guard<std::recursive_mutex> lock(progressMutex);++runEpoch;progress.run=progress.secondary;pending.clear();lastStory=0;Log("engine rollback; restored secondary journal");}
// Rewind (qol_rewind.cpp): note the current point. primary/secondary are older copies of run, so their events are a prefix of run's -> lengths suffice.
RunMark MarkRun(){std::lock_guard<std::recursive_mutex> lock(progressMutex);auto pt=[](const RunState&r){return RunPoint{r.known,r.currentScript,r.currentChoice,r.currentPc,(uint32_t)r.events.size()};};RunMark m;m.epoch=runEpoch;m.run=pt(progress.run);m.primary=pt(progress.primary);m.secondary=pt(progress.secondary);m.pending=pending;m.lastStory=lastStory;return m;}
// Rewind: back to a noted point. Cumulative history (scenes reached, options chosen) stays, like read marks.
bool RewindRun(const RunMark&m){std::lock_guard<std::recursive_mutex> lock(progressMutex);const size_t have=progress.run.events.size();
 if(m.epoch!=runEpoch||m.run.events>have||m.primary.events>m.run.events||m.secondary.events>m.run.events){UnknownRun("rewind: the run journal was replaced since that stop; this run's choices unknown");return false;}
 auto make=[&](const RunPoint&p){RunState r;r.known=p.known;r.currentScript=p.script;r.currentChoice=p.choice;r.currentPc=p.pc;r.events.assign(progress.run.events.begin(),progress.run.events.begin()+p.events);return r;};
 RunState pri=make(m.primary),sec=make(m.secondary),run=make(m.run);progress.primary=std::move(pri);progress.secondary=std::move(sec);progress.run=std::move(run);pending=m.pending;lastStory=m.lastStory;return true;}
void Saved(unsigned slot,const std::wstring&file){std::lock_guard<std::recursive_mutex> lock(progressMutex);std::string hash=DigestFile(file);if(hash.empty()){Log("save fingerprint unavailable; journal not attached");return;}Writer w;w.run(progress.primary);w.run(progress.secondary);std::wstring key(hash.begin(),hash.end());if(write(rootPath+L"\\saves\\"+key+L".dat",w.b))Log("save "+std::to_string(slot)+" fingerprint "+hash);else Log("ERROR save journal could not be written");}
void Loaded(unsigned slot,const std::wstring&file,bool success){std::lock_guard<std::recursive_mutex> lock(progressMutex);if(!success)return;std::string hash=DigestFile(file);std::wstring key(hash.begin(),hash.end());std::vector<uint8_t>b;bool known=!hash.empty()&&read(rootPath+L"\\saves\\"+key+L".dat",b);++runEpoch;RunState a,z;if(known){Reader r{b};a=r.run();z=r.run();known=r.ok&&r.p==b.size();}progress.run=known?a:RunState();progress.primary=progress.run;progress.secondary=known?z:RunState();pending.clear();lastStory=0;Log("load "+std::to_string(slot)+" "+(known?"journal restored ":"prior choices unknown ")+hash);}
}
